{
  "$schema": "https://json.schemastore.org/package.json",
  "name": "@bojackduy/opencode-web-bridges",
  "version": "0.1.2",
  "description": "OpenCode browser bridges: managed ChatGPT and optional local-built Gemini, with provider and MCP registration for v1 and v2.",
  "homepage": "https://bojackduy.github.io/opencode-web-bridges/",
  "type": "module",
  "license": "AGPL-3.0-or-later",
  "private": false,
  "repository": {
    "type": "git",
    "url": "git+https://github.com/bojackduy/opencode-web-bridges.git"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "chatgpt",
    "chatgpt-web",
    "gemini",
    "gemini-web",
    "deepseek",
    "deepseek-web",
    "browser-bridge",
    "llm",
    "openai-compatible",
    "no-api-key",
    "cdp"
  ],
  "files": [
    "bin",
    "dist",
    "commands",
    "tui.js",
    "README.md",
    "LICENSE",
    "CHANGELOG.md"
  ],
  "publishConfig": {
    "access": "public",
    "provenance": true
  },
  "engines": {
    "node": ">=20",
    "bun": ">=1.1.0"
  },
  "bin": {
    "opencode-web-bridges": "./bin/opencode-web-bridges.mjs"
  },
  "exports": {
    ".": {
      "import": "./dist/server.js"
    },
    "./server": {
      "import": "./dist/server.js"
    },
    "./tui": {
      "import": "./dist/tui.js"
    }
  },
  "scripts": {
    "typecheck": "tsc --noEmit",
    "build:server": "bun build src/server/plugin.ts --outfile dist/server.js --target bun --external @opencode-ai/plugin --external @opencode-ai/plugin/tool",
    "build:tui": "bun build src/server/tui.ts --outfile dist/tui.js --target bun",
    "build:installer": "bun build src/installer/install.ts --outfile dist/install.js --target node --external jsonc-parser",
    "build": "bun run build:server && bun run build:tui && bun run build:installer",
    "clean": "rm -rf dist",
    "prepack": "bun run typecheck && bun test && bun run build",
    "test": "bun test",
    "release:patch": "bun run typecheck && bun test && npm version patch -m \"chore: release %s\" && git push && git push origin $(git describe --tags --abbrev=0)",
    "release:minor": "bun run typecheck && bun test && npm version minor -m \"chore: release %s\" && git push && git push origin $(git describe --tags --abbrev=0)",
    "release:major": "bun run typecheck && bun test && npm version major -m \"chore: release %s\" && git push && git push origin $(git describe --tags --abbrev=0)"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": ">=1.4.0 <3"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "^1.18.30",
    "@opencode/plugin": "^2.0.11",
    "@types/bun": "^1.3.14",
    "@types/node": "^26.2.0",
    "typescript": "^5.7.0"
  },
  "dependencies": {
    "jsonc-parser": "^3.3.1"
  }
}
